private fun ImageVector.Builder.wordmark(scale: Float = 1f): ImageVector.Builder = apply {
    addGroup(scaleX = scale, scaleY = scale)
    WORDMARK.forEach { (path, fillType) ->
        addPath(PathParser().parsePathString(path).toNodes(), fill = SolidColor(PlataPalette.Ink), pathFillType = fillType)
    }
    clearGroup()
}

private val plataLogo by lazy {
    // the brand wordmark as wide as the tagline under it
    ImageVector.Builder("plata-logo", 207.dp, 56.14.dp, 207f, 56.14f)
        .wordmark(scale = 207f / 320f)
        .addPath(PathParser().parsePathString(TAGLINE).toNodes(), fill = SolidColor(PlataPalette.Ink))
        .build()
}

private val plataWordmark by lazy {
    ImageVector.Builder("plata-wordmark", 320.dp, 48.dp, 320f, 48f).wordmark().build()
}

/** PLATA wordmark with the "SIMPLEMENTE MARAVILLOSA" tagline, 207×56; monochrome, tint it (white on brand). */
val PlataIcons.PlataLogo: ImageVector get() = plataLogo

/** PLATA wordmark alone, 320×48 (app icon tile, chat avatar); size it to that aspect. */
val PlataIcons.PlataWordmark: ImageVector get() = plataWordmark

private val escudoLogo by lazy {
    val shield = Brush.verticalGradient(
        0f to PlataPalette.EscudoPink,
        0.5f to PlataPalette.EscudoPinkDeep,
        1f to PlataPalette.EscudoCyan,
        startY = 2f,
        endY = 39f,
    )
    val word = Brush.horizontalGradient(
        0f to PlataPalette.EscudoLavender,
        0.3f to PlataPalette.EscudoCyan,
        0.55f to PlataPalette.EscudoLime,
        0.8f to PlataPalette.EscudoPink,
        1f to PlataPalette.EscudoPinkDeep,
        startX = 0f,
        endX = 85.7f,
    )
    val dePlata = Brush.horizontalGradient(0f to PlataPalette.EscudoCyan, 1f to PlataPalette.EscudoCream, startX = 0f, endX = 45.4f)
    ImageVector.Builder("multicolour/escudo-logo", 112.dp, 40.dp, 112f, 40f)
        .addPath(
            pathData = PathParser().parsePathString(ESCUDO_SHIELD).toNodes(),
            stroke = shield,
            strokeLineWidth = 2.2f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
        // the source sets both lines wider than the Figma export: ESCUDO 91×10 and DE PLATA 66 wide (e61c2bc5)
        .addGroup(scaleX = 1.035f, scaleY = 0.964f, translationX = 20f, translationY = 9.2f)
        // the source letters are heavier than the export; an outline in the same paint adds the weight
        .addPath(PathParser().parsePathString(ESCUDO_WORD).toNodes(), fill = word, stroke = word, strokeLineWidth = 0.7f)
        .clearGroup()
        .addGroup(scaleX = 1.458f, translationX = 19.4f, translationY = 24.8f)
        .addPath(PathParser().parsePathString(DE_PLATA).toNodes(), fill = dePlata, stroke = dePlata, strokeLineWidth = 0.4f)
        .clearGroup()
        .build()
}

/** "Escudo de Plata" lockup, 112×40, iridescent (Figma Logo brand=escudo, 82:380); draw untinted. */
val PlataIcons.EscudoLogo: ImageVector get() = escudoLogo
